    "requiredSchema": "`orders_demo` table",
    "codeExample": "CREATE TABLE IF NOT EXISTS `orders_demo` (\n    `order_id` INT AUTO_INCREMENT PRIMARY KEY,\n    `customer` VARCHAR(50) NOT NULL,\n    `status` ENUM('Pending', 'Processing', 'Shipped', 'Delivered', 'Cancelled') DEFAULT 'Pending'\n);\n\nINSERT INTO `orders_demo` (`customer`, `status`)\nVALUES ('Alice', 'Processing'), ('Bob', 'Delivered');\n\nSELECT `order_id`, `customer`, `status` FROM `orders_demo`;",
    "expectedOutput": "+----------+----------+------------+\n| order_id | customer | status     |\n+----------+----------+------------+\n|        1 | Alice    | Processing |\n|        2 | Bob      | Delivered  |\n+----------+----------+------------+\n2 rows in set (0.00 sec)",
    "resultExplanation": "ENUM stores values internally as compact 1-byte or 2-byte integer indices (1 for 'Pending', 2 for 'Processing', etc.), presenting them as strings in query outputs.",
    "notes": "Adding new values to an ENUM requires an ALTER TABLE statement, so use lookup tables instead if the list changes frequently.",
