    "prerequisites": "Parent table with primary key and matching child column.",
    "requiredSchema": "`customers` (parent) and `orders` (child)",
    "codeExample": "USE `codeplay_store`;\n\n-- Create child orders table\nCREATE TABLE IF NOT EXISTS `customer_orders` (\n    `order_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,\n    `customer_id` INT UNSIGNED NOT NULL,\n    `order_total` DECIMAL(10, 2) NOT NULL,\n    `order_date` TIMESTAMP DEFAULT CURRENT_TIMESTAMP\n);\n\n-- Add foreign key constraint linking to customers(customer_id)\nALTER TABLE `customer_orders`\n    ADD CONSTRAINT `fk_orders_customer`\n    FOREIGN KEY (`customer_id`) REFERENCES `customers`(`customer_id`)\n    ON DELETE CASCADE\n    ON UPDATE CASCADE;\n\n-- Confirm foreign key creation\nSELECT CONSTRAINT_NAME, TABLE_NAME, REFERENCED_TABLE_NAME \nFROM information_schema.KEY_COLUMN_USAGE \nWHERE CONSTRAINT_NAME = 'fk_orders_customer';",
    "expectedOutput": "+--------------------+-----------------+-----------------------+\n| CONSTRAINT_NAME    | TABLE_NAME      | REFERENCED_TABLE_NAME |\n+--------------------+-----------------+-----------------------+\n| fk_orders_customer | customer_orders | customers             |\n+--------------------+-----------------+-----------------------+\n1 row in set (0.00 sec)",
    "resultExplanation": "Creates constraint `fk_orders_customer`. Any insertion into `customer_orders` must have a matching `customer_id` in `customers`. Deleting a customer automatically cascades and deletes their orders.",
    "notes": "Data types of child and parent columns must match exactly (e.g. both must be INT UNSIGNED).",
    "commonMistakes": "Mismatched data types or sign (e.g. child INT SIGNED vs parent INT UNSIGNED), causing Error 1215.",
