    "learningObjective": "Exclude known sets of categorical keys or identifiers.",
    "prerequisites": "IN operator.",
    "requiredSchema": "CREATE TABLE employees (id INT, dept VARCHAR(30));",
    "codeExample": "INSERT INTO employees VALUES \n(1, 'Engineering'),\n(2, 'Sales'),\n(3, 'Marketing'),\n(4, 'Executive');\n\nSELECT id, dept FROM employees \nWHERE dept NOT IN ('Sales', 'Marketing');",
    "expectedOutput": "+----+-------------+\n| id | dept        |\n+----+-------------+\n|  1 | Engineering |\n|  4 | Executive   |\n+----+-------------+\n2 rows in set (0.00 sec)",
    "resultExplanation": "Excludes Sales and Marketing, returning Engineering and Executive.",
    "notes": "CRITICAL: If the list contains a NULL value, NOT IN evaluates to UNKNOWN and returns ZERO rows.",
    "commonMistakes": "Using NOT IN with a subquery that returns a NULL value, which unexpectedly yields an empty result set.",
    "requiresNewServer": false,
    "serverTag": "",
    "securityNotes": "Use NOT EXISTS instead of NOT IN when filtering against nullable subqueries.",
    "keywordsOrMethods": [
      "NOT IN",
      "WHERE",
      "Exclusion"
    ]
