    "expectedOutput": "+------+----------------+\n| name | finish_seconds |\n+------+----------------+\n| Sara |           2950 |\n| Mike |           3120 |\n| Alex |           3200 |\n+------+----------------+\n3 rows in set (0.00 sec)",
    "resultExplanation": "Sorts athletes by their finish time from fastest (lowest seconds) to slowest.",
    "notes": "ASC is the default sort direction if no keyword is specified.",
    "commonMistakes": "Assuming SQL returns rows in insertion order without an explicit ORDER BY clause.",
    "requiresNewServer": false,
