    "expectedOutput": "+------------+------------+\n| player     | high_score |\n+------------+------------+\n| CodeMaster |      28900 |\n| RetroGamer |      19800 |\n| PixelNinja |      14200 |\n+------------+------------+\n3 rows in set (0.00 sec)",
    "resultExplanation": "Ranks players starting with the highest score down to the lowest.",
