    "expectedOutput": "+-------------+---------+-----------+\n| dept        | name    | salary    |\n+-------------+---------+-----------+\n| Engineering | Charlie | 110000.00 |\n| Engineering | Alice   |  95000.00 |\n| Sales       | Bob     |  80000.00 |\n| Sales       | David   |  80000.00 |\n+-------------+---------+-----------+\n4 rows in set (0.00 sec)",
