    "prerequisites": "LIMIT and ORDER BY.",
    "requiredSchema": "CREATE TABLE articles (id INT PRIMARY KEY, title VARCHAR(100));",
    "codeExample": "INSERT INTO articles VALUES \n(1, 'Post 1'), (2, 'Post 2'), (3, 'Post 3'), \n(4, 'Post 4'), (5, 'Post 5'), (6, 'Post 6');\n\n-- Page 2: Page size 2, offset (page-1)*2 = 2\nSELECT id, title \nFROM articles \nORDER BY id ASC \nLIMIT 2 OFFSET 2;",
    "expectedOutput": "+----+--------+\n| id | title  |\n+----+--------+\n|  3 | Post 3 |\n|  4 | Post 4 |\n+----+--------+\n2 rows in set (0.00 sec)",
    "resultExplanation": "Skips the first 2 records (Post 1 and Post 2) and returns the next 2 (Post 3 and Post 4).",
    "notes": "Alternative syntax: LIMIT offset, count (e.g. LIMIT 2, 2).",
    "commonMistakes": "Deep offsets (e.g. OFFSET 1000000) cause performance degradation because MySQL must read and discard all preceding rows.",
