    "introduction": "The HAVING clause filters aggregated results after GROUP BY, whereas WHERE filters individual rows before grouping.",
    "learningObjective": "Filter summary groups based on aggregate conditions (e.g., groups with COUNT > 1).",
    "prerequisites": "WHERE vs GROUP BY execution order.",
    "requiredSchema": "CREATE TABLE orders (customer_id INT, order_val DECIMAL(10,2));",
    "codeExample": "INSERT INTO orders VALUES \n(101, 250), (102, 40), (101, 300), (103, 15), (101, 120), (102, 60);\n\n-- Find customers who made at least 2 orders totaling over 200\nSELECT \n    customer_id, \n    COUNT(*) AS order_count,\n    SUM(order_val) AS total_spent\nFROM orders\nGROUP BY customer_id\nHAVING COUNT(*) >= 2 AND SUM(order_val) > 200;",
    "expectedOutput": "+-------------+-------------+-------------+\n| customer_id | order_count | total_spent |\n+-------------+-------------+-------------+\n|         101 |           3 |      670.00 |\n+-------------+-------------+-------------+\n1 row in set (0.00 sec)",
    "resultExplanation": "Groups orders by customer, then filters out customers whose aggregate count or sum falls below the threshold.",
    "notes": "WHERE filters source rows before grouping; HAVING filters aggregate buckets after grouping.",
    "commonMistakes": "Placing non-aggregate conditions in HAVING that belong in WHERE, causing unnecessary grouping overhead.",
    "requiresNewServer": false,
