    "codeExample": "INSERT INTO students VALUES (1, 'Maya'), (2, 'Leo');\nINSERT INTO courses VALUES (10, 'Computer Science'), (20, 'Calculus');\nINSERT INTO enrollments VALUES (1, 10, 'A'), (1, 20, 'A-'), (2, 10, 'B+');\n\nSELECT s.name AS student, c.title AS course, e.grade\nFROM students s\nINNER JOIN enrollments e ON s.id = e.student_id\nINNER JOIN courses c ON e.course_id = c.id\nORDER BY s.name, c.title;",
    "expectedOutput": "+---------+------------------+-------+\n| student | course           | grade |\n+---------+------------------+-------+\n| Leo     | Computer Science | B+    |\n| Maya    | Calculus         | A-    |\n| Maya    | Computer Science | A     |\n+---------+------------------+-------+\n3 rows in set (0.00 sec)",
