    "title": "Anti-Join (Left Join WHERE NULL)",
    "cleanTitle": "Anti-Join (Left Join WHERE NULL)",
    "category": "SQL Joins",
    "introduction": "An anti-join finds rows in the left table that have NO matching rows in the right table using LEFT JOIN ... WHERE right.key IS NULL.",
    "learningObjective": "Detect orphan records, inactive users, or unsold inventory items efficiently.",
    "prerequisites": "LEFT JOIN and IS NULL logic.",
    "requiredSchema": "CREATE TABLE users (id INT PRIMARY KEY, name VARCHAR(50));\nCREATE TABLE orders (order_id INT, user_id INT);",
    "codeExample": "INSERT INTO users VALUES (1, 'Active Amy'), (2, 'Dormant Dan'), (3, 'Silent Sam');\nINSERT INTO orders VALUES (101, 1), (102, 1);\n\n-- Find users who have NEVER placed an order\nSELECT u.id, u.name\nFROM users u\nLEFT JOIN orders o ON u.id = o.user_id\nWHERE o.order_id IS NULL\nORDER BY u.id;",
