    "resultExplanation": "Identifies Dan and Sam because their LEFT JOIN results produced NULL for order_id.",
    "notes": "Anti-joins using LEFT JOIN ... IS NULL are frequently faster and more NULL-safe than NOT IN (subquery).",
    "commonMistakes": "Filtering on a nullable column in the right table rather than the primary key or join key.",
    "requiresNewServer": false,
    "serverTag": "",
    "securityNotes": "Crucial pattern for clean-up scripts and retention marketing segmentation.",
