    "title": "Window Function: ROW_NUMBER()",
    "cleanTitle": "Window Function: ROW_NUMBER()",
    "category": "Advanced SQL Queries",
    "introduction": "ROW_NUMBER() assigns a unique, sequential integer to each row within a designated partition or sort order.",
    "learningObjective": "Enumerate rows deterministically for pagination, rankings, or deduplication.",
    "prerequisites": "Window functions and OVER() clause.",
    "requiredSchema": "CREATE TABLE products (id INT, category VARCHAR(30), name VARCHAR(50), price DECIMAL(8,2));",
