    "expectedOutput": "+-------------+-------------+--------------+---------+\n| rank_in_cat | category    | name         | price   |\n+-------------+-------------+--------------+---------+\n|           1 | Electronics | Laptop       | 1200.00 |\n|           2 | Electronics | Headphones   |  150.00 |\n|           1 | Furniture   | Desk Chair   |  250.00 |\n|           2 | Furniture   | Coffee Table |  180.00 |\n+-------------+-------------+--------------+---------+\n4 rows in set (0.00 sec)",
    "resultExplanation": "Ranks items 1 and 2 within each category based on descending price.",
    "notes": "ROW_NUMBER() always generates unique consecutive integers without gaps or ties.",
    "commonMistakes": "Attempting to filter ROW_NUMBER() directly in the WHERE clause (window functions evaluate after WHERE; wrap in a CTE).",
    "requiresNewServer": false,
    "serverTag": "",
    "securityNotes": "Ideal for top-N-per-group queries in modern MySQL 8.0.",
