    "prerequisites": "ROW_NUMBER() and OVER().",
    "requiredSchema": "CREATE TABLE contest (contestant VARCHAR(50), score INT);",
    "codeExample": "INSERT INTO contest VALUES \n('Alice', 100), ('Bob', 90), ('Charlie', 90), ('David', 80);\n\nSELECT \n    contestant, score,\n    RANK() OVER (ORDER BY score DESC) AS standard_rank,\n    DENSE_RANK() OVER (ORDER BY score DESC) AS dense_rank\nFROM contest;",
    "expectedOutput": "+------------+-------+---------------+------------+\n| contestant | score | standard_rank | dense_rank |\n+------------+-------+---------------+------------+\n| Alice      |   100 |             1 |          1 |\n| Bob        |    90 |             2 |          2 |\n| Charlie    |    90 |             2 |          2 |\n| David      |    80 |             4 |          3 |\n+------------+-------+---------------+------------+\n4 rows in set (0.00 sec)",
    "resultExplanation": "Bob and Charlie tie at rank 2. RANK() jumps to 4 for David, while DENSE_RANK() advances cleanly to 3.",
