    "cleanTitle": "Create Index (Single Column)",
    "category": "Database Design and Advanced Features",
    "introduction": "An index is a B-tree data structure that accelerates WHERE filtering and ORDER BY operations from O(N) to O(log N).",
    "learningObjective": "Create single-column B-tree indexes on frequently queried search keys.",
    "prerequisites": "Table creation and performance fundamentals.",
    "requiredSchema": "CREATE TABLE customers (id INT PRIMARY KEY, email VARCHAR(100), full_name VARCHAR(100));",
    "codeExample": "-- Create index on email\nCREATE INDEX idx_customers_email ON customers (email);\n\n-- Inspect table indexes\nSHOW INDEX FROM customers WHERE Column_name = 'email';",
    "expectedOutput": "+-----------+------------+---------------------+--------------+-------------+\n| Table     | Non_unique | Key_name            | Seq_in_index | Column_name |\n+-----------+------------+---------------------+--------------+-------------+\n| customers |          1 | idx_customers_email |            1 | email       |\n+-----------+------------+---------------------+--------------+-------------+\n1 row in set (0.00 sec)",
    "resultExplanation": "Creates a secondary B-tree index on the email column and verifies its presence via SHOW INDEX.",
    "notes": "Indexes accelerate SELECT queries but impose a slight write penalty during INSERT, UPDATE, and DELETE.",
    "commonMistakes": "Over-indexing every column in a table, causing slow write performance and high disk consumption.",
    "requiresNewServer": false,
    "serverTag": "",
    "securityNotes": "Ensure high-frequency lookup columns have indexes to prevent resource-exhausting full table scans.",
