    "introduction": "A BEFORE INSERT trigger automatically executes code before a new row is written to disk, allowing validation or field mutation.",
    "learningObjective": "Enforce data validation and automatically format text using the NEW pseudo-row.",
    "prerequisites": "Table constraints and stored routines.",
    "requiredSchema": "CREATE TABLE contacts (id INT AUTO_INCREMENT PRIMARY KEY, email VARCHAR(100));",
    "codeExample": "-- [REQUIRES NEW SERVER]\nDELIMITER //\nCREATE TRIGGER trg_contacts_before_insert\nBEFORE INSERT ON contacts\nFOR EACH ROW\nBEGIN\n    -- Automatically trim and lowercase emails\n    SET NEW.email = LOWER(TRIM(NEW.email));\nEND //\nDELIMITER ;\n\nINSERT INTO contacts (email) VALUES ('  DevAlice@Example.COM  ');\nSELECT * FROM contacts;",
    "expectedOutput": "+----+-----------------------+\n| id | email                 |\n+----+-----------------------+\n|  1 | devalice@example.com  |\n+----+-----------------------+\n1 row in set (0.00 sec)",
    "resultExplanation": "The BEFORE INSERT trigger cleaned the input whitespace and lowercased the characters prior to disk commit.",
    "notes": "The NEW keyword provides access to the pending column values before they are written.",
    "commonMistakes": "Attempting to modify NEW values in an AFTER INSERT trigger (AFTER triggers are read-only).",
