    "codeExample": "-- [REQUIRES NEW SERVER]\nCREATE TABLE historical_sales (\n    order_id INT,\n    order_date DATE NOT NULL,\n    amount DECIMAL(10,2),\n    PRIMARY KEY (order_id, order_date)\n)\nPARTITION BY RANGE (YEAR(order_date)) (\n    PARTITION p2024 VALUES LESS THAN (2025),\n    PARTITION p2025 VALUES LESS THAN (2026),\n    PARTITION p2026 VALUES LESS THAN (2027),\n    PARTITION p_max VALUES LESS THAN MAXVALUE\n);\n\n-- Pruned query scans only the p2026 partition segment\nEXPLAIN SELECT * FROM historical_sales WHERE order_date = '2026-10-23';",
    "expectedOutput": "+----+-------------+------------------+------------+------+\n| id | select_type | table            | partitions | type |\n+----+-------------+------------------+------------+------+\n|  1 | SIMPLE      | historical_sales | p2026      | ALL  |\n+----+-------------+------------------+------------+------+\n1 row in set (0.00 sec)",
    "resultExplanation": "The query planner prunes partitions p2024, p2025, and p_max, scanning solely partition p2026.",
    "notes": "Every column used in the partitioning expression must be part of every unique key (including primary key).",
