    "cleanTitle": "Pagination with PHP and MySQL (LIMIT, OFFSET)",
    "category": "PHP + MySQL",
    "introduction": "Pagination computes `offset = (page - 1) * perPage` and passes both parameters as integers into LIMIT/OFFSET clauses.",
    "learningObjective": "Implement standard page-based data pagination and calculate total page counts.",
    "prerequisites": "LIMIT, OFFSET, and COUNT(*).",
    "requiredSchema": "CREATE TABLE articles (id INT PRIMARY KEY, title VARCHAR(100));",
    "codeExample": "<?php\n// [REQUIRES NEW SERVER]\n$pdo = new PDO('mysql:host=127.0.0.1;dbname=playcode', 'user', 'pass');\n\n$page = 2;\n$perPage = 10;\n$offset = ($page - 1) * $perPage;\n\n// Total items\n$totalRows = $pdo->query('SELECT COUNT(*) FROM articles')->fetchColumn();\n$totalPages = ceil($totalRows / $perPage);\n\n$stmt = $pdo->prepare('SELECT id, title FROM articles ORDER BY id ASC LIMIT :limit OFFSET :offset');\n$stmt->bindValue(':limit', $perPage, PDO::PARAM_INT);\n$stmt->bindValue(':offset', $offset, PDO::PARAM_INT);\n$stmt->execute();\n\necho \"Displaying Page {$page} of {$totalPages}\";\n?>",
    "expectedOutput": "Displaying Page 2 of 5",
    "resultExplanation": "Binds explicit integer limits and offsets to display page 2 cleanly.",
    "notes": "Must use bindValue with PDO::PARAM_INT when PDO::ATTR_EMULATE_PREPARES is disabled, because LIMIT rejects strings.",
    "commonMistakes": "Passing string offsets to MySQL with emulated prepares off, causing syntax errors.",
    "requiresNewServer": true,
    "serverTag": "[REQUIRES NEW SERVER]",
    "securityNotes": "Sanitize page inputs: `$page = max(1, (int)($_GET['page'] ?? 1))`.",
    "keywordsOrMethods": [
      "LIMIT",
      "OFFSET",
      "PDO::PARAM_INT",
      "Pagination Math"
    ]
