    "codeExample": "<?php\n// [REQUIRES NEW SERVER]\n$pdo = new PDO('mysql:host=127.0.0.1;dbname=playcode', 'user', 'pass');\n\n$stmt = $pdo->query('SELECT id, name, email FROM customers LIMIT 2');\n$fp = fopen('php://memory', 'w');\n\n// Write Header\nfputcsv($fp, ['ID', 'Customer Name', 'Email Address']);\n\nwhile ($row = $stmt->fetch(PDO::FETCH_ASSOC)) {\n    fputcsv($fp, $row);\n}\n\nrewind($fp);\necho stream_get_contents($fp);\nfclose($fp);\n?>",
    "expectedOutput": "ID,\"Customer Name\",\"Email Address\"\n1,\"Diana Prince\",diana@themyscira.io\n2,\"Bruce Wayne\",bruce@waynecorp.com",
    "resultExplanation": "Writes header and each customer row to memory using fputcsv(), handling quotes and commas properly.",
    "notes": "Streaming row-by-row uses constant O(1) PHP memory even when exporting 100,000 rows.",
    "commonMistakes": "Building CSV by manual string concatenation with commas (fails on quotes or embedded newlines).",
