    "codeExample": "<?php\n// [REQUIRES NEW SERVER]\nheader('Content-Type: application/json; charset=utf-8');\n\n$pdo = new PDO('mysql:host=127.0.0.1;dbname=playcode', 'user', 'pass');\n$stmt = $pdo->query('SELECT id, name, CAST(price AS FLOAT) AS price FROM products LIMIT 2');\n$data = $stmt->fetchAll(PDO::FETCH_ASSOC);\n\n$payload = [\n    'status'  => 'success',\n    'count'   => count($data),\n    'results' => $data\n];\n\necho json_encode($payload, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES);\n?>",
