    "codeExample": "CREATE TABLE users (id INT PRIMARY KEY, handle VARCHAR(50));\nCREATE TABLE friendships (user_id INT, friend_id INT, PRIMARY KEY (user_id, friend_id));\n\nINSERT INTO users VALUES (1, 'Alice'), (2, 'Bob'), (3, 'Charlie'), (4, 'David');\n-- Alice's friends: Charlie, David\nINSERT INTO friendships VALUES (1, 3), (1, 4);\n-- Bob's friends: Charlie\nINSERT INTO friendships VALUES (2, 3);\n\n-- Find mutual friends between Alice (id 1) and Bob (id 2)\nSELECT u.handle AS mutual_friend\nFROM friendships f1\nINNER JOIN friendships f2 ON f1.friend_id = f2.friend_id\nINNER JOIN users u ON f1.friend_id = u.id\nWHERE f1.user_id = 1 AND f2.user_id = 2;",
    "expectedOutput": "+---------------+\n| mutual_friend |\n+---------------+\n| Charlie       |\n+---------------+\n1 row in set (0.00 sec)",
    "resultExplanation": "Joins Alice's friends with Bob's friends on matching friend_id to reveal Charlie as the mutual friend.",
    "notes": "Composite primary key (user_id, friend_id) prevents duplicate friendship connections.",
