    "introduction": "A running total accumulates values chronologically over time using `SUM() OVER (ORDER BY ...)`.",
    "learningObjective": "Generate cumulative bank balances and progressive revenue streams.",
    "prerequisites": "Window functions and ORDER BY in OVER.",
    "requiredSchema": "CREATE TABLE bank_ledger (tx_date DATE, amount DECIMAL(10,2));",
    "codeExample": "INSERT INTO bank_ledger VALUES \n('2026-10-01', 500.00),\n('2026-10-02', -120.00),\n('2026-10-03', 250.00),\n('2026-10-04', -50.00);\n\nSELECT \n    tx_date, amount,\n    SUM(amount) OVER (ORDER BY tx_date) AS running_balance\nFROM bank_ledger;",
    "expectedOutput": "+------------+---------+-----------------+\n| tx_date    | amount  | running_balance |\n+------------+---------+-----------------+\n| 2026-10-01 |  500.00 |          500.00 |\n| 2026-10-02 | -120.00 |          380.00 |\n| 2026-10-03 |  250.00 |          630.00 |\n| 2026-10-04 |  -50.00 |          580.00 |\n+------------+---------+-----------------+\n4 rows in set (0.00 sec)",
    "resultExplanation": "Calculates progressive running balance after each transaction: 500 -> 380 -> 630 -> 580.",
    "notes": "The default window framing when ORDER BY is present is `RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW`.",
    "commonMistakes": "Omitting ORDER BY inside OVER(), which sums the entire table instead of accumulating progressively.",
    "requiresNewServer": false,
    "serverTag": "",
    "securityNotes": "Running totals in SQL execute in memory without mutating stored table records.",
    "keywordsOrMethods": [
      "Running Total",
      "Cumulative Sum",
      "Window Frame",
      "UNBOUNDED PRECEDING"
    ]
