    "requiredSchema": "CREATE TABLE annual_financials (fiscal_year INT, revenue DECIMAL(12,2));",
    "codeExample": "INSERT INTO annual_financials VALUES \n(2024, 1000000.00), (2025, 1250000.00), (2026, 1600000.00);\n\nSELECT \n    fiscal_year, revenue,\n    LAG(revenue) OVER (ORDER BY fiscal_year) AS prev_year_revenue,\n    ROUND(((revenue - LAG(revenue) OVER (ORDER BY fiscal_year)) / LAG(revenue) OVER (ORDER BY fiscal_year)) * 100, 2) AS yoy_growth_pct\nFROM annual_financials;",
