    "cleanTitle": "Soft Delete Pattern with is_deleted and deleted_at",
    "category": "Additional Practical Examples",
    "introduction": "Soft deletion marks records as deleted using a timestamp or boolean flag without permanently removing table rows from disk.",
    "learningObjective": "Implement recoverable deletion workflows and design views that automatically filter out soft-deleted rows.",
    "prerequisites": "UPDATE statements and CREATE VIEW.",
    "requiredSchema": "CREATE TABLE customers (id INT PRIMARY KEY, name VARCHAR(50), deleted_at DATETIME DEFAULT NULL);",
    "codeExample": "INSERT INTO customers VALUES (1, 'Alice Active', NULL), (2, 'Bob Terminated', NOW());\n\n-- Create active view excluding soft-deleted rows\nCREATE VIEW v_active_customers AS\nSELECT id, name FROM customers WHERE deleted_at IS NULL;\n\n-- Perform soft delete on Alice\nUPDATE customers SET deleted_at = NOW() WHERE id = 1;\n\nSELECT * FROM v_active_customers;",
    "expectedOutput": "Empty set (0.00 sec)",
    "resultExplanation": "Both Alice and Bob have non-NULL deleted_at values, so v_active_customers returns an empty set.",
    "notes": "Soft deletes allow easy undelete/restore workflows and preserve foreign key referential integrity.",
    "commonMistakes": "UNIQUE constraints collision (e.g. unique email) when a soft-deleted record prevents re-registration.",
    "requiresNewServer": false,
    "serverTag": "",
    "securityNotes": "Ensure compliance with GDPR 'Right to be Forgotten' by executing physical hard deletes when legally requested.",
