    "introduction": "MySQL Full-Text Search (FTS) indexes natural language text and returns relevance scores using MATCH() AGAINST().",
    "learningObjective": "Create FULLTEXT indexes and execute relevance-ranked search queries on text articles.",
    "prerequisites": "FULLTEXT index creation.",
    "requiredSchema": "CREATE TABLE articles (\n    id INT AUTO_INCREMENT PRIMARY KEY,\n    title VARCHAR(150),\n    body TEXT,\n    FULLTEXT KEY ft_articles (title, body)\n);",
    "codeExample": "INSERT INTO articles (title, body) VALUES \n('MySQL Performance Guide', 'Indexes and query caching maximize database throughput.'),\n('Gardening Basics', 'Spring planting tips for organic tomatoes and peppers.'),\n('Relational Database Design', 'Primary keys and foreign keys normalize MySQL database schemas.');\n\n-- Search articles for 'database performance'\nSELECT title, ROUND(MATCH(title, body) AGAINST('database performance' IN NATURAL LANGUAGE MODE), 2) AS relevance\nFROM articles\nWHERE MATCH(title, body) AGAINST('database performance' IN NATURAL LANGUAGE MODE)\nORDER BY relevance DESC;",
    "expectedOutput": "+----------------------------+-----------+\n| title                      | relevance |\n+----------------------------+-----------+\n| MySQL Performance Guide    |      0.82 |\n| Relational Database Design |      0.35 |\n+----------------------------+-----------+\n2 rows in set (0.00 sec)",
    "resultExplanation": "Finds relevant articles and ranks them by mathematical relevance score (0.82 vs 0.35).",
    "notes": "Natural Language Mode is the default mode if no modifier is specified.",
