    "requiresNewServer": false,
    "serverTag": "",
    "securityNotes": "FTS is dramatically faster than LIKE '%keyword%' and scales to millions of articles.",
    "keywordsOrMethods": [
      "FULLTEXT",
      "MATCH() AGAINST()",
      "NATURAL LANGUAGE MODE",
      "Relevance Scoring"
    ]
